() => {
  // Get all text content on the page to find filter/section labels
  const results = [];
  document.querySelectorAll('h1, h2, h3, h4, h5, h6, [data-testid*="topic"], [data-testid*="section"], [data-testid*="filter"]').forEach(el => {
    const text = el.textContent.trim();
    if (text) results.push({tag: el.tagName, testid: el.dataset.testid, text: text.substring(0, 200)});
  });
  return results;
}()

return (function() {
  const results = [];
  document.querySelectorAll('h1, h2, h3, h4, h5, h6, [data-testid*="topic"], [data-testid*="section"], [data-testid*="filter"]').forEach(el => {
    const text = el.textContent.trim();
    if (text) results.push({tag: el.tagName, testid: el.dataset.testid, text: text.substring(0, 200)});
  });
  return results;
})()

return (function() {
  // Get all button text and links in the page
  const results = [];
  document.querySelectorAll('button, a, [role="tab"], [role="button"]').forEach(el => {
    const text = el.textContent.trim();
    const testid = el.dataset.testid || '';
    if (text && text.length < 100) results.push({tag: el.tagName, testid: testid, text: text});
  });
  return results;
})()

return (function() {
  const results = [];
  // Look for all headings and section labels on the page
  document.querySelectorAll('h1, h2, h3, h4, h5, h6, [class*="section"], [class*="heading"], [data-testid*="section"], [data-testid*="heading"]').forEach(el => {
    const text = el.textContent.trim();
    if (text && text.length < 200 && (text.toLowerCase().includes('war') || text.toLowerCase().includes('conflict'))) {
      results.push({tag: el.tagName, testid: el.dataset.testid, text: text});
    }
  });
  return results;
})()

return (function() {
  const results = [];
  // Look for all section labels and headings that are NOT article headlines
  document.querySelectorAll('[data-testid*="section"], [data-testid*="title"], [data-testid*="label"], [aria-label]').forEach(el => {
    const text = el.textContent.trim();
    const testid = el.dataset.testid || '';
    const aria = el.getAttribute('aria-label') || '';
    if (text && text.length < 100 && !testid.includes('card-headline')) {
      results.push({tag: el.tagName, testid: testid, aria: aria, text: text});
    }
  });
  // Also look for h2/h3 headings
  document.querySelectorAll('h2, h3').forEach(el => {
    const text = el.textContent.trim();
    const testid = el.dataset.testid || '';
    if (text && text.length < 100 && !testid.includes('card-headline')) {
      results.push({tag: el.tagName, testid: testid, text: text});
    }
  });
  return results;
})()
